// Brackets quote actual revision cards. Text keys keep the story stable if cards are reordered.
const reiseStory=[
['Der gelbe Koffer','Toufik und Lina fahren morgen zu einer Hochzeit in Berlin. Auf dem Dachboden finden sie einen alten gelben Koffer. Er gehört ihrem Bruder Sami. Darin liegt nur ein Zettel: „Vergesst die Ringe nicht!“',
'Toufik schaut auf den leeren Koffer. [Ich brauche einen Koffer für die Reise.] Lina lacht: „Nimm doch diesen!“ Sie selbst reist lieber mit wenig Gepäck. [Ich nehme meinen Rucksack mit.]',
'Toufik macht eine Liste. [Ich packe meinen Reisepass ein.] Lina legt ihr Telefon auf den Tisch. [Ich nehme mein Handy mit.] Dann fragt sie: [Hast du deine Kreditkarte dabei?] Toufik nickt. Für die Feier im Garten fehlt Lina noch etwas: [Ich brauche eine Sonnencreme.]'],
['Ein Plan für die Hochzeit','Sami ruft an. Er sitzt noch zu Hause vor dem Computer. [Er bucht seine Reise online.] „Und ihr? Was kauft ihr online?“, fragt er. Toufik sagt: [Ich bestelle Bücher im Internet.] Für die Zugfahrt hat er einen Tipp: [Man kann E-Books schnell herunterladen.]',
'Lina erzählt von ihrer Freundin Mia: [Sie kauft ihre Kleidung online.] Lina selbst geht gern auf den Markt: [Lebensmittel kaufe ich lieber im Geschäft.] Sami vergleicht zwei Ringkästchen auf dem Bildschirm und zeigt auf eins: [Dieses Produkt ist billiger.] Kurz darauf sagt er: [Ich muss noch die Bestellung bezahlen.]',
'Für die Kleidung bleibt keine Zeit mehr für ein Paket. Lina und Toufik gehen in die Stadt. Unterwegs fragt Lina: [Was trägst du gern?] Toufik antwortet: [Ich trage gern T-Shirts und Jeans.] Aber für die Hochzeit möchte er etwas anderes.'],
['Vor dem Spiegel','Im Schaufenster sieht Lina drei Sachen: [Der Pullover ist grün.] [Die Jacke ist schwarz.] [Das Hemd ist weiß.] Toufik schaut auf einen Anzug: [Ich finde diesen Anzug sehr schick.] Im Laden sagt er: [Ich suche einen schwarzen Anzug.]',
'Die Verkäuferin fragt: [Welche Größe haben Sie?] „Meistens 48.“ Sie zeigt ihm ein Hemd. Toufik fragt: [Kann ich dieses Hemd anprobieren?] Die Verkäuferin zeigt nach links: [Die Umkleidekabine ist dort hinten.]',
'Das Hemd passt, aber Toufik erklärt: [Meine Lieblingsfarbe ist Blau.] Er fragt: [Haben Sie das auch in Blau?] Die Verkäuferin bringt ein blaues Hemd. [Wie viel kostet das Hemd?] „Zwanzig Euro.“ Toufik ist zufrieden: [Ich nehme das blaue Hemd.]'],
['Zu lang, zu eng','Jetzt ist Lina dran. [Kann ich die Jacke anprobieren?] Vor dem Spiegel merkt sie: [Die Jacke ist mir zu eng.] Sie ruft: [Haben Sie das eine Nummer größer?] Die nächste passt. Lina fragt: [Wie viel kostet die Jacke?] „Hundert Euro.“ Lina hängt sie zurück: [Das ist mir zu teuer.]',
'Bei den Hosen hilft ihr ein Verkäufer. [Welche Größe brauchen Sie?] „Größe 38, bitte.“ Lina probiert eine Hose an: [Die Hose ist mir zu lang.] Sie fragt: [Haben Sie die Hose auch eine Nummer kleiner?]',
'Als Nächstes probiert sie eine Bluse. [Die Bluse ist zu groß.] [Haben Sie eine Nummer kleiner?] Leider gibt es keine mehr. Da entdeckt sie ein rotes Kleid: [Kann ich das anprobieren?] Diesmal passt alles. [Ich nehme das rote Kleid.]'],
['Die verschwundenen Ringe','An der Kasse fragt Lina noch: [Kann ich das Kleid umtauschen?] „Ja, mit dem Kassenbon.“ Neben ihr steht Sami! Sein Zug geht erst am Abend. Er hält ein Geschenk in der Hand: [Kann ich den Pullover umtauschen?] Statt des Pullovers möchte er etwas für die Braut: [Ich hätte gern diesen Schal.]',
'Am nächsten Morgen steht Sami schon an der Tür. Lina trägt ihre neuen Schuhe. Sami sagt: [Deine Schuhe sehen toll aus!] Doch Toufik sucht plötzlich seinen Pass. [Ich fahre nicht ohne meinen Reisepass.] Alle drei öffnen den gelben Koffer.',
'Unter dem blauen Hemd liegt der Pass. Und in der kleinen Seitentasche? Zwei goldene Ringe! Sami nimmt sie an sich. „Den Koffer dürft ihr behalten“, sagt er, „aber die Ringe brauche ich heute selbst!“ Jetzt versteht Toufik den Zettel. Gemeinsam laufen sie zum Bahnhof.']
];
function showReiseStory(ch,cards,back){
 const {title,scenes}=ch===8?{title:'Der gelbe Koffer',scenes:reiseStory}:chapterStories[ch];
 const meanings=new Map(cards.map(([ar,de])=>[de,ar]));
 const line=s=>s.split(/(\[[^\]]+\])/g).map(part=>{if(!part.startsWith('['))return esc(part);const de=part.slice(1,-1);return '<button type="button" class="storyPhrase" aria-expanded="false">'+esc(de)+'</button><span class="storyMeaning" lang="ar-MA" dir="rtl" hidden>'+esc(meanings.get(de)||'')+'</span>'}).join('');
 app.innerHTML='<button id="storyBack">'+revL('رجع للعبارات','Zurück zu den Redemitteln')+'</button><section class="hero"><span class="cap">Kapitel '+ch+' · '+cards.length+' '+revL('عبارة','Redemittel')+'</span><h2 lang="de" dir="ltr">'+esc(title)+'</h2><p>'+revL('قرا القصة بالألمانية. ضغط على أي عبارة باللون الفيروزي باش تشوف المعنى ديالها بالدارجة.','Tippe auf einen türkisfarbenen Satz, um seine Bedeutung auf Darija zu sehen.')+'</p></section>'+scenes.map(([title,...paras])=>'<article class="card storyScene" lang="de" dir="ltr"><h3>'+esc(title)+'</h3>'+paras.map(p=>'<p>'+line(p)+'</p>').join('')+'</article>').join('')+'<button id="storyEnd">'+revL('رجع للعبارات','Zurück zu den Redemitteln')+'</button>';
 for(const b of app.querySelectorAll('.storyPhrase'))b.onclick=()=>{const s=b.nextElementSibling;s.hidden=!s.hidden;b.setAttribute('aria-expanded',String(!s.hidden))};
 $('#storyBack').onclick=$('#storyEnd').onclick=back;window.scrollTo(0,0);
}
